 3→import { NextResponse } from 'next/server'
 4→
 5→/**
 6→ * Simple token-based authentication middleware
 7→ * @param {Function} handler - The route handler to protect
 8→ * @returns {Function} - Protected route handler
 9→ */
10→export function adminAuth(handler) {
11→  return async (req, context) => {
12→    try {
13→      // Check for authorization header
14→      const authHeader = req.headers.get('Authorization');
15→
16→      if (!authHeader || !authHeader.startsWith('Bearer ')) {
17→        return new NextResponse(JSON.stringify({ error: 'Unauthorized - Missing or invalid token' }), {
18→          status: 401,
19→          headers: { 'Content-Type': 'application/json' }
20→        });
21→      }
22→
23→      const token = authHeader.split(' ')[1];
24→      const adminToken = process.env.NEXT_PUBLIC_ADMIN_API_KEY;
25→
26→      // Check if the token matches the admin API key
27→      if (token !== adminToken) {
28→        return new NextResponse(JSON.stringify({ error: 'Forbidden: Admin access required' }), {
29→          status: 403,
30→          headers: { 'Content-Type': 'application/json' }
31→        });
32→      }
33→
34→      // User is authenticated and authorized as admin, proceed with the request
35→      // Pass through context (which includes params for dynamic routes)
36→      return handler(req, context);
37→    } catch (error) {
38→      console.error('Auth error:', error);
39→      return new NextResponse(JSON.stringify({ error: 'Authentication error' }), {
40→        status: 500,
41→        headers: { 'Content-Type': 'application/json' }
42→      });
43→    }
44→  };
45→}
