/**
 * Seed script to create an admin user via BetterAuth's admin plugin API.
 * Usage: node scripts/seed-admin.mjs
 */

const BASE_URL = 'http://localhost:3000';

async function seedAdmin() {
  const email = 'admin@gregorytaylor.com';
  const password = 'Admin2024!secure';
  const name = 'Admin';

  // Use BetterAuth's admin plugin endpoint to create a user
  // The admin plugin exposes POST /api/auth/admin/create-user
  const res = await fetch(`${BASE_URL}/api/auth/admin/create-user`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      email,
      password,
      name,
      role: 'admin',
    }),
  });

  if (!res.ok) {
    const text = await res.text();
    console.error(`Failed (${res.status}): ${text}`);

    // Fallback: try the sign-up endpoint directly (works via internal API)
    console.log('Trying sign-up endpoint...');
    const signUpRes = await fetch(`${BASE_URL}/api/auth/sign-up/email`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password, name }),
    });

    if (!signUpRes.ok) {
      const signUpText = await signUpRes.text();
      console.error(`Sign-up also failed (${signUpRes.status}): ${signUpText}`);
      process.exit(1);
    }

    const signUpData = await signUpRes.json();
    console.log('User created via sign-up:', signUpData);
    return;
  }

  const data = await res.json();
  console.log('Admin user created:', data);
}

seedAdmin().catch(console.error);

