  process.env.BETTER_AUTH_DB_PATH || path.join(process.cwd(), 'auth.db')
const db = new Database(dbPath)

export const auth = betterAuth({
  secret: process.env.BETTER_AUTH_SECRET,
  database: db,
  emailAndPassword: {
    enabled: true,
    disableSignUp: true,
    minPasswordLength: 8,
  },
  session: {
    expiresIn: 60 * 60 * 24 * 7, // 7 days in seconds
