const getPhotoImageSettings = async (photoId) => {
  try {
    if (!photoId) throw new Error('photoId is required')

    const base = process.env.NEXT_PUBLIC_API_BASE
    if (!base) throw new Error('API base URL is not defined')

    const res = await fetch(`${base}/api/admin/photos/${encodeURIComponent(photoId)}/image-settings`, { credentials: 'include' })

    if (!res.ok) {
      throw new Error(`Failed to fetch photo image settings: ${res.status} ${res.statusText}`)
    }

    return await res.json()
  } catch (error) {
    handleApiError(error, 'getPhotoImageSettings')
    throw error
  }
}

const updatePhotoImageSettings = async (photoId, settings) => {
  try {
    if (!photoId) throw new Error('photoId is required')

    const base = process.env.NEXT_PUBLIC_API_BASE
    if (!base) throw new Error('API base URL is not defined')

    const res = await fetch(`${base}/api/admin/photos/${encodeURIComponent(photoId)}/image-settings`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(settings),
      credentials: 'include'
    })

    if (!res.ok) {
      throw new Error(`Failed to update photo image settings: ${res.status} ${res.statusText}`)
    }

    return await res.json()
  } catch (error) {
    handleApiError(error, 'updatePhotoImageSettings')
    throw error
  }
}

