15→export async function POST(request) {
16→  try {
17→    const { items, userId } = await request.json();
18→
19→    const line_items = items.map(item => ({
20→      price_data: {
21→        currency: 'usd',
22→        product_data: { name: item.title },
23→        unit_amount: Math.round(item.unitPrice * 100),
24→      },
25→      quantity: item.quantity || 1,
26→    }));
27→
28→    const origin = request.headers.get('origin') || '';
29→    const session = await getStripe().checkout.sessions.create({
30→      payment_method_types: ['card'],
31→      line_items,
32→      mode: 'payment',
33→      success_url: `${origin}/cart/success?session_id={CHECKOUT_SESSION_ID}`,
34→      cancel_url: `${origin}/cart/cancel`,
35→      metadata: { userId: userId || '' },
36→    });
37→
38→    // Persist order in backend
