40→      method: 'POST',
41→      headers: { 'Content-Type': 'application/json' },
42→      body: JSON.stringify({ 
43→        stripeSessionId: session.id,
44→        paymentIntentId: session.payment_intent,
45→        items,
46→        totalAmount: items.reduce((sum, i) => sum + i.unitPrice * (i.quantity||1), 0),
47→        currency: 'usd',
48→        userId,
49→      }),
50→    });
51→
52→    return NextResponse.json({ id: session.id });
53→  } catch (err) {
54→    console.error('Checkout API error:', err);
55→    return NextResponse.json({ error: 'Unable to create session' }, { status: 500 });
56→  }
57→}
