export async function getPhotoImageSettings(photoId) {
  if (!photoId) throw new Error('photoId is required')

  const res = await fetch(`/api/admin/photos/${encodeURIComponent(photoId)}/image-settings`, { credentials: 'include' })

  if (!res.ok) {
    throw new Error(`Failed to fetch photo image settings: ${res.status} ${res.statusText}`)
  }

  return res.json()
}

export async function updatePhotoImageSettings(photoId, settings) {
  if (!photoId) throw new Error('photoId is required')

  const res = await fetch(`/api/admin/photos/${encodeURIComponent(photoId)}/image-settings`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(settings),
    credentials: 'include'
  })

  if (!res.ok) {
    throw new Error(`Failed to update photo image settings: ${res.status} ${res.statusText}`)
  }

  return res.json()
}

